visual.source:
flowchart TB
  subgraph G5["5 記録を調べる"]
    LK@{ svc: "AWS CloudTrail", label: "CloudTrail Lake<br/>SQL で調べる" }
  end
  subgraph G4["4 いつもと違う動き"]
    AN["CloudTrail の<br/>Insights events<br/>CloudWatch の<br/>異常検出"]
  end
  subgraph G3["3 脅威を見つける"]
    GD@{ svc: "Amazon GuardDuty", label: "GuardDuty<br/>脅威の検出" }
    SH@{ svc: "AWS Security Hub CSPM", label: "Security Hub CSPM<br/>検出結果を受ける" }
  end
  subgraph G2["2 ルールで確かめる"]
    CFG@{ svc: "AWS Config", label: "AWS Config ルール<br/>ずれと危ない設定" }
  end
  subgraph G1["1 記録を残す"]
    CT@{ svc: "AWS CloudTrail", label: "CloudTrail<br/>監査とログの完全性" }
    FL@{ svc: "Amazon VPC", label: "VPC Flow Logs<br/>通信の記録" }
  end

flowchart TB
  CFG@{ svc: "AWS Config", label: "AWS Config<br/>iam-external-access-<br/>analyzer-enabled" }
  subgraph ACC["1 つのアカウント"]
    R1@{ svc: "IAM Access Analyzer", label: "IAM Access Analyzer<br/>外部アクセス用<br/>リージョン A" }
    R2@{ svc: "IAM Access Analyzer", label: "IAM Access Analyzer<br/>外部アクセス用<br/>リージョン B" }
  end
  CFG -- "有効か" --> R1
  CFG -- "有効か" --> R2

flowchart TB
  subgraph SRC["findings を送る側の例"]
    GD@{ svc: "Amazon GuardDuty", label: "Amazon GuardDuty" }
    IN@{ svc: "Amazon Inspector", label: "Amazon Inspector" }
    MA@{ svc: "Amazon Macie", label: "Amazon Macie" }
    TP["対応する<br/>他社の製品"]
  end
  SH@{ svc: "AWS Security Hub CSPM", label: "Security Hub CSPM<br/>control findings も作る<br/>ASFF で処理" }
  GD --> SH
  IN --> SH
  MA --> SH
  TP --> SH

flowchart TB
  subgraph G5["5 記録を調べる"]
    LK@{ svc: "AWS CloudTrail", label: "CloudTrail Lake<br/>新規受付の停止" }
  end
  subgraph G4["4 いつもと違う動き"]
    AN["API の使い方は<br/>Insights events<br/>メトリクスは<br/>異常検出"]
  end
  subgraph G3["3 脅威を見つける"]
    GD@{ svc: "Amazon GuardDuty", label: "GuardDuty<br/>EventBridge へ" }
    SH@{ svc: "AWS Security Hub CSPM", label: "Security Hub CSPM<br/>ASFF で処理" }
  end
  subgraph G2["2 ルールで確かめる"]
    CFG@{ svc: "AWS Config", label: "AWS Config ルール<br/>違反の条件を読む" }
  end
  subgraph G1["1 記録を残す"]
    CT@{ svc: "AWS CloudTrail", label: "CloudTrail<br/>改ざんに気付ける" }
    FL@{ svc: "Amazon VPC", label: "VPC Flow Logs<br/>VPC やサブネットなど" }
  end
